from typing import List

class Solution:
    def countPairs(self, deliciousness: List[int]) -> int:
        MOD = 1000000007
        freq = {}
        ans = 0
        max_value = max(deliciousness)
        power = 1
        powers = []
        while power <= 2 * max_value:
            powers.append(power)
            power <<= 1
        for x in deliciousness:
            for p in powers:
                ans = (ans + freq.get(p - x, 0)) % MOD
            freq[x] = freq.get(x, 0) + 1
        return ans

