import java.io.*;
import java.util.*;

class Solution {
    public int countPairs(int[] deliciousness) {
        final long MOD = 1000000007L;
        Map<Integer, Integer> freq = new HashMap<>();
        long ans = 0;
        int maxValue = 0;
        for (int x : deliciousness) maxValue = Math.max(maxValue, x);
        for (int x : deliciousness) {
            for (int power = 1; power <= 2 * maxValue; power <<= 1) {
                int need = power - x;
                ans = (ans + freq.getOrDefault(need, 0)) % MOD;
            }
            freq.put(x, freq.getOrDefault(x, 0) + 1);
        }
        return (int) ans;
    }
}

