#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL
#define MAXV 1048576

int countPairs(int* deliciousness, int n) {
    int *freq = (int*)calloc(MAXV + 1, sizeof(int));
    long long ans = 0;
    int maxValue = 0;
    for (int i = 0; i < n; ++i) if (deliciousness[i] > maxValue) maxValue = deliciousness[i];

    for (int i = 0; i < n; ++i) {
        int x = deliciousness[i];
        for (int power = 1; power <= 2 * maxValue; power <<= 1) {
            int need = power - x;
            if (need >= 0 && need <= MAXV) {
                ans += freq[need];
                if (ans >= MOD) ans %= MOD;
            }
        }
        ++freq[x];
    }
    ans %= MOD;
    free(freq);
    return (int)ans;
}

